        available_non=[dt for dt in non_specialty_types if dt in reduced_cand]
        for r in range(len(available_non)+1):
            for non_combo in itertools.combinations(available_non, r):
                district_list = list(spec_combo) + list(non_combo)
                district_list.sort(key=lambda d: len(reduced_cand[d]))

                used=set([cc])
                placements={cc: DistrictType.CITY_CENTER}

                def backtrack(i):
                    nonlocal best
                    if i==len(district_list):
                        total, per = adj_calc.calculate_total_adjacency(placements)
                        if best is None or total>best[0]:
                            best=(total, cc, placements.copy())
                        return
                    dt=district_list[i]
                    for pos in reduced_cand[dt]:
                        if pos in used:
                            continue
                        used.add(pos)
                        placements[pos]=dt
                        backtrack(i+1)
                        used.remove(pos)
                        placements.pop(pos)

                backtrack(0)

print('best', best)
